src/math.laws.ts::counting up reaches n.source:
law.proved('counting up reaches n', (n: int) => {
  assume(n >= 0 && n < 1_000_000);
  return countUp(n) === n;
});

calls.countUp:
export function countUp(n: int): int {
  let i = 0;
  while (i < n) {
    i = i + 1;
  }
  return i as int;
}

calls.largest:
export function largest(xs: int[]): int {
  let m = 0;
  let i = 0;
  while (i < xs.length) {
    if (xs[i] > m) m = xs[i];
    i += 1;
  }
  return m as int;
}

src/math.laws.ts::the average sits betwe.source:
law('the average sits between', (a: number, b: number) => {
  assume(a >= 0 && a <= b && b <= 1_000_000);
  return average(a, b) >= a && average(a, b) <= b;
});

calls.average:
export function average(a: number, b: number): number {
  return (a + b) / 2;
}

src/math.laws.ts::half is at most n.source:
law.proved('half is at most n', (n: int) => {
  assume(n >= 0 && n < 1_000_000);
  return half(n) <= n;
});

calls.half:
export function half(n: int): int {
  return Math.floor(n / 2) as int;
}

src/math.laws.ts::clamping never goes be.source:
law.proved('clamping never goes below the floor', (x: int, lo: int) => {
  assume(small(x) && small(lo));
  return clampAbove(x, lo) >= lo;
});

calls.clampAbove:
export function clampAbove(x: int, lo: int): int {
  return (x < lo ? lo : x) as int;
}
